namespace kotatsu {

/// The bytes a UTF-8 decoder takes from the start of a text: their length,
/// whether they make a code point, and the code point they make, U+FFFD when
/// they do not. An ill-formed sequence is its maximal subpart, the longest
/// prefix of a code point it starts with and at least one byte, which a
/// decoder replaces with one U+FFFD.
struct UTF8Sequence {
    char32_t code_point;
    std::size_t length;
    bool valid;
};

namespace detail {

/// decode_utf8(), taking a surrogate for a code point when `surrogates`
/// says so: WTF-8, the superset that spells a lone one.
constexpr UTF8Sequence decode_sequence(std::string_view text, bool surrogates) {
    constexpr char32_t replacement = 0xFFFD;
    auto lead = static_cast<unsigned char>(text[0]);
    if(lead < 0x80) {
        return {.code_point = lead, .length = 1, .valid = true};
    }
    // The range of the second byte narrows for the leads whose code points
    // would be overlong, surrogates or past U+10FFFF.
    std::size_t need = 0;
    char32_t code_point = 0;
    unsigned char low = 0x80;
    unsigned char high = 0xBF;
    if(lead >= 0xC2 && lead <= 0xDF) {
        need = 2;
        code_point = lead & 0x1F;
    } else if(lead >= 0xE0 && lead <= 0xEF) {
        need = 3;
        code_point = lead & 0x0F;
        low = lead == 0xE0 ? 0xA0 : low;
        high = lead == 0xED && !surrogates ? 0x9F : high;
    } else if(lead >= 0xF0 && lead <= 0xF4) {
        need = 4;
        code_point = lead & 0x07;
        low = lead == 0xF0 ? 0x90 : low;
        high = lead == 0xF4 ? 0x8F : high;
    } else {
        return {.code_point = replacement, .length = 1, .valid = false};
    }
    std::size_t length = 1;
    while(length < need && length < text.size()) {
        auto next = static_cast<unsigned char>(text[length]);
        if(next < low || next > high) {
            break;
        }
        code_point = (code_point << 6) | (next & 0x3F);
        low = 0x80;
        high = 0xBF;
        ++length;
    }
    if(length != need) {
        return {.code_point = replacement, .length = length, .valid = false};
    }
    return {.code_point = code_point, .length = length, .valid = true};
}

}  // namespace detail

/// The sequence at the start of text, which is not empty. A code point is
/// none overlong, a surrogate or past U+10FFFF.
constexpr UTF8Sequence decode_utf8(std::string_view text) {
    return detail::decode_sequence(text, false);
}

/// Where text cut at `at` keeps only whole sequences: `at` where a sequence
/// starts there, else the start of the sequence `at` falls inside; the size
/// of text for an `at` past its end. The sequences are those decode_utf8()
/// reads from the start, so in text that is no UTF-8 a byte that continues
/// no sequence is one of its own.
constexpr std::size_t floor_char_boundary(std::string_view text, std::size_t at) {
    if(at >= text.size()) {
        return text.size();
    }
    auto continues = [&](std::size_t i) {
        return (static_cast<unsigned char>(text[i]) & 0xC0) == 0x80;
    };
    // A sequence is one byte that continues none and at most three that do.
    std::size_t start = at;
    while(start > 0 && at - start < 3 && continues(start)) {
        --start;
    }
    if(continues(start) || start + decode_utf8(text.substr(start)).length <= at) {
        return at;
    }
    return start;
}

/// Whether text is UTF-8: whole code points, none overlong, a surrogate or
/// past U+10FFFF. ASCII passes eight bytes at a time.
inline bool is_utf8(std::string_view text) {
    if(!any_word(text, 0, [](std::uint64_t word) { return has_non_ascii(word); })) {
        return true;
    }
    for(std::size_t at = 0; at < text.size();) {
        if(text.size() - at >= sizeof(std::uint64_t)) {
            std::uint64_t word;
            std::memcpy(&word, text.data() + at, sizeof(word));
            if(!has_non_ascii(word)) {
                at += sizeof(word);
                continue;
            }
        }
        auto sequence = decode_utf8(text.substr(at));
        if(!sequence.valid) {
            return false;
        }
        at += sequence.length;
    }
    return true;
}

/// text as a UTF-8 decoder reads it: each maximal subpart of an ill-formed
/// sequence replaced with U+FFFD.
inline std::string replace_invalid_utf8(std::string_view text) {
    std::string result;
    result.reserve(text.size());
    for(std::size_t at = 0; at < text.size();) {
        auto sequence = decode_utf8(text.substr(at));
        if(sequence.valid) {
            result.append(text.substr(at, sequence.length));
        } else {
            result.append("\xEF\xBF\xBD");
        }
        at += sequence.length;
    }
    return result;
}

}  // namespace kotatsu

